// Loads only the fixed scalar credential schema generated by up.sh. It runs
// supported real browser scenarios without exporting or printing credentials.
// #102's UI-revealed runtime token is relayed only to Plinth's attached-stdin
// CLI, never persisted in the browser report, environment, or a local file.
import { readFileSync } from "node:fs";
import { spawn, spawnSync } from "node:child_process";

const file = process.env.QUOIN_E2E_CREDENTIALS_FILE;
if (!file) throw new Error("QUOIN_E2E_CREDENTIALS_FILE is required");
const values = Object.fromEntries(readFileSync(file, "utf8").split("\n").flatMap((line) => {
	const match = /^(url|username|temporaryPassword|password): (.+)$/.exec(line.trim());
	return match ? [[match[1], match[2]]] : [];
}));
for (const key of ["url", "username", "temporaryPassword", "password"]) {
	if (!values[key]) throw new Error(`generated credentials.yaml lacks ${key}`);
}
const repoRoot = new URL("../../", import.meta.url).pathname;
const helper = `${repoRoot}scripts/e2e-real/register-plinth.sh`;

const result = spawnSync("pnpm", ["--dir", "web", "test:e2e:real"], {
	cwd: repoRoot,
	stdio: "inherit",
	env: {
		...process.env,
		QUOIN_REAL_E2E_BASE_URL: values.url,
		QUOIN_E2E_ADMIN_USERNAME: values.username,
		QUOIN_E2E_ADMIN_PASSWORD: values.temporaryPassword,
		QUOIN_E2E_ADMIN_FINAL_PASSWORD: values.password,
		QUOIN_E2E_REGISTER_PLINTH_HELPER: helper,
	},
});
process.exit(result.status ?? 1);
